select (select string_agg(schemaname||'.'||tablename, ', ' order by tablename) from pg_publication_tables where pubname='supabase_realtime') pub_tables, (select count(*) from pg_publication where pubname='supabase_realtime') pub_exists, (select string_agg(relname||':'||relreplident::text, ',' order by relname) from pg_class where relnamespace='public'::regnamespace and relname in ('orders','payments','task_status','order_signatures','order_lot_pictures','order_pictures')) replident;
